"""Integrate recovered research into a preserved DOCX, never regenerate from Git.
Writes a private candidate; publication to the main path follows inspection.
"""
import csv, hashlib, json, re
from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
ROOT=Path(__file__).resolve().parents[1]
PRIVATE=ROOT/'.local/research-2026-10-08'
original=PRIVATE/'tcc_antonewton.docx'
doc=Document(original);old=list(doc.paragraphs)
a=json.loads((ROOT/'docs/research/aggregate.json').read_text());freq=a['frequencies'];qual=a['qualitative']
def replace(i,s):
 p=old[i]
 # Retain paragraph style/properties and first run formatting.
 for run in p.runs[1:]:run.text=''
 if p.runs:p.runs[0].text=s
 else:p.add_run(s)
def add(anchor,text,style='Normal'):
 return anchor.insert_paragraph_before(text, old[80].style if style=='Heading 2' else old[78].style)
def table(anchor,title,headers,rows,note='Fonte: elaboração própria a partir das respostas recuperadas (análise de 8 out. 2026). N = 24; percentagens sobre 24 registos, salvo indicação; arredondamento a uma casa decimal.'):
 p=add(anchor,'Tabela X — '+title);p.paragraph_format.keep_with_next=True
 t=doc.add_table(rows=1,cols=len(headers));t.style=doc.tables[0].style
 t.autofit=False
 widths=([4.4,.8,1.0] if len(headers)==3 else [1.8,.88,.88,.88,.88,.88] if len(headers)==6 else [3.2,1.0,1.0,1.0])
 if headers[0]=='Campo':widths=[.6,3.6,1.0,1.0]
 if headers[0]=='Perfil':widths=[2.5,.6,1.55,1.55]
 for col,w in zip(t.columns,widths):col.width=Inches(w)
 for c,s in zip(t.rows[0].cells,headers):c.text=s
 trpr=t.rows[0]._tr.get_or_add_trPr();el=OxmlElement('w:tblHeader');trpr.append(el)
 for row in rows:
  for c,s in zip(t.add_row().cells,row):c.text=str(s)
 for r in t.rows:
  prop=r._tr.get_or_add_trPr();prop.append(OxmlElement('w:cantSplit'))
  for c,w in zip(r.cells,widths):
   c.width=Inches(w)
   for p in c.paragraphs:
    p.alignment=WD_ALIGN_PARAGRAPH.LEFT;p.paragraph_format.first_line_indent=Inches(0)
    p.paragraph_format.keep_with_next=True
    p.paragraph_format.space_after=Pt(3);p.paragraph_format.space_before=Pt(3);p.paragraph_format.line_spacing=1
    for run in p.runs:run.font.size=Pt(10)
 anchor._p.addprevious(t._tbl);add(anchor,note)
 return t
def pct(n,base=24):return f'{100*n/base:.1f}'.replace('.',',')
def value(v,cat):return next(r['n'] for r in freq if r['variable']==v and r['category']==cat)
def npercent(n):return f'{n} ({pct(n)}%)'
def rowsfor(v):return [[r['category'],r['n'],str(r['percent']).replace('.',',')] for r in freq if r['variable']==v]
def simple(anchor,v,title):table(anchor,title,['Resposta','n','%'],rowsfor(v))
def figure(anchor,title,file):
 p=add(anchor,'Figura X — '+title);p.paragraph_format.keep_with_next=True
 p=add(anchor,'');p.add_run().add_picture(str(ROOT/'docs/research/figures'/file),width=Inches(6.1))
 add(anchor,'Fonte: elaboração própria a partir das respostas recuperadas (2026). N = 24 por item; ausentes = 0. Os números nas barras são contagens de respostas.')

for i in (4,8,15):replace(i,'PLATAFORMA DE CAPTAÇÃO DE FUNDOS PARA STARTUPS ACELERADAS EM ANGOLA')
replace(34,'Este trabalho apresenta o desenvolvimento do SEED, uma plataforma de apoio à organização e ao acompanhamento da captação de fundos para startups aceleradas em Angola. O âmbito compreende perfis, rondas, negociações, interações, documentos e indicadores, sem processamento de pagamentos ou intermediação financeira. A investigação é aplicada e exploratória, com revisão bibliográfica e documental, levantamento de perceções e desenvolvimento de um artefacto de software. Em 8 de outubro de 2026 foram analisadas 24 submissões recuperadas de um questionário, todas com consentimento afirmativo, mediante frequências, percentagens e categorização descritiva das respostas abertas. A identidade única dos participantes não é certificável. Dezoito registos indicam um processo pouco estruturado ou sem definição clara e vinte expressam muito interesse ou interesse máximo na ideia. Predominam respostas autodeclaradas de startups, num grupo heterogéneo sem representatividade estatística demonstrada. A análise posterior confirma alinhamentos e evidencia limites de decisões de projeto já existentes; não reconstitui essas decisões como derivadas originalmente dos resultados. A implementação utiliza Next.js, React e PostgreSQL, com autorização por recurso, histórico de etapas e acesso documental explícito. A evidência técnica anterior documenta persistência, isolamento e recuperação local; nesta revisão efetuou-se leitura do código e desses registos. Conclui-se que o protótipo oferece meios técnicos de organização e rastreabilidade compatíveis com parte das necessidades declaradas. Interesse e utilidade percebida não demonstram adoção, usabilidade, eficácia ou aumento do financiamento, dimensões que exigem avaliação futura com participantes.')
replace(38,'This study presents SEED, a platform supporting the organization and monitoring of post-acceleration fundraising for startups in Angola. Its scope includes profiles, rounds, negotiations, interactions, documents and process indicators, without payment processing or financial intermediation. The applied exploratory study combines bibliographic and documentary review, a perception survey and software development. On 8 October 2026, 24 recovered questionnaire submissions, all with affirmative consent, were analysed using frequencies, percentages and descriptive categorization of open answers. Unique participant identities cannot be certified. Eighteen records describe weakly structured or undefined processes, while twenty express high or maximum interest in the proposed idea. Self-reported startup profiles predominate within a heterogeneous group without demonstrated statistical representativeness. This later analysis assesses alignment with previously existing design decisions rather than claiming that the findings originally determined them. The implementation uses Next.js, React and PostgreSQL, with resource-level authorization, stage history and explicit document access grants. Earlier technical evidence documents local persistence, isolation and recovery; this revision inspected the code and existing records. The prototype provides technical means of organizing and tracing fundraising that align with some reported needs. Declared interest and perceived usefulness do not demonstrate adoption, usability, effectiveness or increased funding, which require future participant-based evaluation.')
replace(78,'O trabalho tem como domínio a organização da captação de fundos após programas de aceleração. O SEED reúne informações de startups, rondas, potenciais investidores e documentos num fluxo rastreável. A pergunta de investigação é: de que forma uma plataforma digital pode apoiar a organização e o acompanhamento do processo de captação de fundos para startups aceleradas em Angola? A resposta combina um levantamento exploratório de perceções, analisado após a recuperação dos dados, e a demonstração técnica do protótipo local. A eficácia em utilização real permanece por avaliar.')
replace(79,'O diagnóstico da economia digital de Angola identifica barreiras de financiamento no empreendedorismo digital (World Bank Group, 2023). Esse enquadramento não estabelece que a dispersão documental seja a dificuldade predominante das startups aceleradas angolanas. As 24 submissões analisadas permitem descrever perceções do grupo consultado, mas não estimar prevalências nacionais ou efeitos causais do sistema.')
replace(81,'O levantamento recuperado aborda organização, acompanhamento das negociações, documentos e indicadores. Dezoito das 24 respostas referem um processo pouco estruturado ou sem definição clara. Os resultados e as opiniões divergentes são apresentados no capítulo 5, sem transformar problemas declarados em diagnóstico de todo o ecossistema. No plano de engenharia, o repositório inicialmente disponibilizava páginas com dados simulados e ações sem persistência; a implementação documentada passou a utilizar PostgreSQL e autorização no servidor.')
replace(98,'Conceção e avaliação técnica de um sistema de informação dirigido ao contexto angolano, confrontadas com um levantamento exploratório de perceções. As contas fictícias do software não são participantes nem representam entidades reais do levantamento.')
replace(87,'Analisar o instrumento e as respostas recuperadas, caracterizar o grupo consultado e confrontar as necessidades interpretadas com requisitos candidatos, explicitando a origem e os limites da evidência.')
replace(122,'A investigação é aplicada e exploratória, com revisão bibliográfica e documental, levantamento descritivo de necessidades e perceções e desenvolvimento de software. A revisão bibliográfica é narrativa e orientada ao problema, sem protocolo de revisão sistemática. A análise reúne frequências de itens fechados e categorização de textos breves; não se reivindica um desenho formal de métodos mistos apenas pela coexistência desses formatos. Distinguem-se o levantamento, a construção do protótipo, a verificação técnica e a futura avaliação de usabilidade ou eficácia com pessoas.')
replace(124,'Em 8 de outubro de 2026 foram recuperados e inspecionados o PDF “Plataforma de Captação de Fundos para Startups Aceleradas em Angola – Google Forms” e a exportação XLSX de respostas. O PDF tem 240 páginas, organizadas em 24 formulários individuais de dez páginas, com perguntas, opções e respostas assinaladas, incluindo contactos. Não contém um resumo gráfico agregado. A planilha tem uma folha visível, “Respostas do Formulário 1”, 24 linhas de dados e 33 colunas: carimbo temporal, 31 campos de investigação/participação e um contacto opcional. As grelhas desdobram-se em cinco colunas cada. O Apêndice A transcreve o instrumento sem respostas pessoais; Q01–Q20 são identificadores atribuídos nesta análise, não numeração original.')
replace(125,'A revisão documental anterior, de 7 de outubro de 2026, registava a indisponibilidade dos dados. Essa limitação foi resolvida pela recuperação dos ficheiros; não há evidência de aplicação de testes do protótipo aos respondentes. As datas observadas na planilha vão de 5 a 10 de fevereiro de 2026, sem indicação de fuso horário e sem comprovar o período completo de divulgação. O protótipo e decisões de projeto antecedem esta análise dos dados recuperados; os resultados são usados para confirmar, rever ou questionar o alinhamento atual, não para atribuir retroativamente a sua origem ao questionário.')
add(old[126],'Segundo informação prestada pelo autor em 8 de outubro de 2026, o questionário foi divulgado entre estudantes, colaboradores e diretores de startups, investidores do mercado formal/bolsa e colaboradores da Anda Angola. Trata-se de relato posterior do autor, sem lista de convidados, canais, procedimento de seleção ou período completo documentados. Os perfis autodeclarados não permitem verificar a pertença a cada grupo de divulgação nem equiparar investidores em bolsa a investidores de startups. Não se demonstrou amostragem probabilística; não se calculam taxa de resposta, margem de erro ou estimativas populacionais. A explicitação dessas lacunas segue o princípio de transparência metodológica da American Association for Public Opinion Research ([s. d.]).')
replace(127,'As decisões de tratamento foram estabelecidas em 8 de outubro de 2026, após a recuperação, e não constituem um plano pré-registado. Incluíram-se as submissões com consentimento afirmativo para descrição das perceções do grupo consultado; respostas negativas ou sem consentimento seriam excluídas. Não se exigiu pertencer a um dos três perfis centrais, nem residência exclusiva em Angola. Todas as 24 submissões consentem e mencionam Angola, pelo que nenhuma foi excluída. Não foram encontrados registos integralmente repetidos ou vetores idênticos após retirar data e contacto. Semelhança parcial, opinião desfavorável e perfil minoritário não motivaram exclusão. A amostra analítica é de 24 registos de resposta, sem certificação de 24 pessoas únicas.')
replace(128,'Os originais foram preservados com hashes SHA-256 e proveniência numa área privada ignorada pelo Git. A cópia de análise conserva valores originais e aplica apenas remoção de espaços exteriores e representação inteira dos valores 1–5. Categorias geográficas compostas foram mantidas. A seleção múltipla foi separada por correspondência com as opções completas do PDF, preservando vírgulas internas e respostas “Outra”. Frequências absolutas e percentagens usam 24 como denominador explícito; ausências são apresentadas como categoria, sem redistribuição. Os itens ordinais mantêm a ordem original, sem médias, índices, testes inferenciais ou coeficientes de fiabilidade. Agregações descritivas de categorias adjacentes são identificadas no texto e acompanhadas das distribuições completas. A concordância com perda de oportunidades tem sentido distinto dos quatro itens positivos e não foi somada a estes.')
add(old[129],'As respostas abertas foram lidas integralmente e agrupadas por conteúdo manifesto. A unidade de contexto é a resposta a cada pergunta; a unidade de codificação é uma ideia expressa. Uma resposta pode receber várias categorias, mas cada categoria conta uma vez por registo e pergunta. As categorias foram formuladas nesta revisão e a atribuição foi conferida contra cada texto; regras explícitas no script reproduzem a classificação deste corpus, sem pretensão de classificador geral. A codificação foi assistida por inteligência artificial nesta revisão, com regras explícitas implementadas em Python; a revisão académica pelo autor permanece necessária. Não houve segundo codificador independente, cálculo de concordância ou demonstração de saturação. Campos vazios, “Não”, “Melhor não” e “N/A” nos comentários são distinguidos de conteúdo temático. Uma formulação ambígua sobre a relação com investidores conserva categoria própria e não é interpretada como acusação. Não se publicam citações individuais. As contagens representam registos com menção, não pessoas identificadas nem intensidade do problema.')
replace(130,'O instrumento anuncia anonimato e recolhe contacto opcional na mesma submissão. Vinte dos 24 registos incluem contacto, todos com resposta afirmativa ao interesse em contacto futuro; as vinte cadeias normalizadas são distintas, sem comprovar identidade ou unicidade de pessoas. Assim, não se afirma anonimato absoluto. Os contactos foram separados da cópia analítica e permanecem em ficheiro privado com permissões restritas; originais identificáveis também são privados. O relatório contém apenas agregados e não cruza localidades, contactos ou textos que permitam reconhecer indivíduos. Nenhum participante foi contactado. Uma futura recolha deverá separar o formulário de contactos, esclarecer finalidades e definir retenção institucional; esta recomendação não modifica retroativamente o instrumento aplicado. A configuração original de identificação automática não é verificável pela exportação.')
replace(133,'Os critérios originais de seleção do âmbito foram coerência do domínio, viabilidade académica e demonstração ponta-a-ponta. A análise recuperada permite confrontar essas decisões com preferências declaradas, sem as converter em requisitos obrigatórios. A matriz no Apêndice B e em docs/traceability.csv distingue respostas analisadas, conteúdo do instrumento, literatura e decisão de projeto. Sugestões ausentes aparecem como propostas; a prioridade de engenharia não é uma ordenação automática das frequências.')
replace(136,'Não foi localizado um manual institucional específico de apresentação do TFC nos ficheiros disponibilizados ou na pesquisa do portal do ISPTEC. O portal disponibiliza regulamentos académicos, que não substituem tal manual. Preservaram-se a identificação institucional, o autor, o orientador, os estilos e a sequência temática do documento. A banca e a data de aprovação permanecem por confirmar. As edições das normas foram reconferidas em 8 de outubro de 2026; sem acesso às normas integrais e ao manual, não se declara conformidade institucional integral.')
replace(139,'A área operacional /workspace apresenta painéis por papel e páginas próprias para consulta, criação e edição. A revisão de interface documentada em 8 de outubro de 2026 acrescenta pesquisa e paginação de oito registos no navegador. A startup pode gerir perfil, rondas, negociações, interações e documentos; investidores e aceleradoras consultam relações autorizadas. A identidade visual foi preservada. Nesta fase documental, a aplicação e a base de dados não foram alteradas nem se repetiram testes que criam registos.')
replace(174,'As histórias de utilização descrevem decisões de projeto: manter perfil e ronda; associar investidor e preservar interações; acompanhar etapas, intenções e term sheets; partilhar documentos com destinatário explícito; e consultar relações autorizadas como investidor ou aceleradora. A análise posterior encontra preferências compatíveis com essas capacidades, mas não comprova que todas tenham sido originalmente solicitadas por participantes nem que bastem para os seus processos.')
